export const params = { rsiLow: 30, stopAtr: 1.5, size: 0.05 };
export const bounds = { rsiLow: { min: 10, max: 50, step: 5 }, stopAtr: { min: 0.5, max: 4, step: 0.5 }, size: { min: 0.01, max: 0.1, step: 0.01 } };
export function decide(x: Input, p: typeof params): Decision {
  const rsi = x.features['ta.rsi14'];
  const atr = x.features['ta.atr14'];
  if (typeof rsi !== 'number' || typeof atr !== 'number') return null;
  if (rsi < p.rsiLow) return { side: 'long', size: p.size, stop: p.stopAtr * atr, tp: 2 * p.stopAtr * atr };
  if (rsi > 100 - p.rsiLow) return { side: 'flat', size: 0 };
  return null;
}
export const describe = 'Buy oversold RSI dips with an ATR stop and a 2R target.';

export const params = { minVolRatio: 1.5, stopAtr: 2, size: 0.05 };
export const bounds = { minVolRatio: { min: 1, max: 3, step: 0.1 }, stopAtr: { min: 0.5, max: 4, step: 0.5 }, size: { min: 0.01, max: 0.1, step: 0.01 } };
export function decide(x: Input, p: typeof params): Decision {
  const up = x.features['ta.hull21.crossUp'];
  const down = x.features['ta.hull21.crossDown'];
  const vr = x.features['volume.volRatio'];
  const atr = x.features['ta.atr14'];
  if (typeof vr !== 'number' || typeof atr !== 'number') return null;
  if (up === true && vr > p.minVolRatio) return { side: 'long', size: p.size, stop: p.stopAtr * atr };
  if (down === true && vr > p.minVolRatio) return { side: 'short', size: p.size, stop: p.stopAtr * atr };
  return null;
}
export const describe = 'Trade Hull 21 crosses in both directions when volume is above average.';
